            self.last_port_map = port_map;
        } else {
            self.last_port_map = vec![0];
        }
        match self.active_notes.remove(&midi) {
            Some(harmonies) => {
                let mut result = vec![note];
                result.extend(harmonies);
                result
            }
            None => vec![note], // No tracked harmony, just return original
        }
    }
